INSERT INTO CHB_DATACHECK_RULE_INV ("CHECKRULEID", "PAGE_ID", "CHECKMETHOD", "SRCPROPERTY", "COMPARETO", "OBJVALUE", "NULLABLE", "REMARK", "STATUS", "CHECKCLASS") VALUES ('CHB_PRD_DECLARE_INFO_2022_03_07_1057', 'SvrPerProDeclareInfo002', 'invAssetTypeAndPercent', 'invTypeRat', NULL, '(((\d{1,3}(.\d{1,2})?%)|(\d{1,3}(.\d{1,2})?%-\d{1,3}(.\d{1,2})?%)):[\u4e00-\u9fa5_a-zA-Z0-9()_]+;)*(((\d{1,3}(.\d{1,2})?%)|(\d{1,3}(.\d{1,2})?%-\d{1,3}(.\d{1,2})?%)):[\u4e00-\u9fa5_a-zA-Z0-9()_]+)', 'Y', '投资资产种类及比例要素格式不对。正确的格式：数字%：文字；数字%-数字%：文字（其中，百分号、冒号、分号、连字号均应为英文标点，文字和数字部分均不得含有英文百分号、冒号、分号、连字号）。其中，数字格式为n..（5，2），且需大于等于0、小于等于100', 'E', 'com.joyintech.service.chb.common.service.ChbBaseCheckLib');
